// =====================================================================
// CONFIGURATION — reprise du Zap Zapier « Facturation natio »
// TODO : recopier To/Cc/Objet/prénom depuis le Zap d'origine avant de
// le couper.
// =====================================================================
const TO        = 'samia@athena-bs.fr';                       // TODO vérifier
const CC        = 'elodie@athena-bs.fr, lisa@athena-bs.fr';   // TODO vérifier
const SUBJECT   = 'Dépôt de facture - Natio';                 // TODO vérifier
const GREETING  = '';                                         // prénom pour « Hello X, » ; vide = « Bonjour, »
const FROM_NAME = 'thibaud@athena-bs.fr';

// =====================================================================

const out = [];

for (const item of $input.all()) {
  // Le trigger n8n livre le payload webhook complet : { event_id, event_type, form_response }
  const fr = item.json.form_response || item.json;

  // Les réponses référencent les champs par id ; les intitulés sont dans
  // definition.fields du payload.
  const titleById = {};
  for (const f of (fr.definition && fr.definition.fields) || []) {
    titleById[f.id] = (f.title || '').trim();
  }

  const answers = {};
  for (const a of fr.answers || []) {
    const title = titleById[(a.field && a.field.id) || ''] || '';
    let val = '';
    switch (a.type) {
      case 'choice':   val = a.choice && (a.choice.label || a.choice.other); break;
      case 'choices':  val = a.choices && (a.choices.labels || []).join(', '); break;
      case 'text':     val = a.text; break;
      case 'date':     val = a.date; break;
      case 'number':   val = String(a.number); break;
      case 'boolean':  val = a.boolean ? 'Oui' : 'Non'; break;
      case 'email':    val = a.email; break;
      case 'file_url': val = a.file_url; break;
      default:         val = a[a.type] != null ? String(a[a.type]) : '';
    }
    if (title) answers[title] = val || '';
  }

  const exact = (t) => answers[t] || '';
  const byPrefix = (p) => {
    for (const [t, v] of Object.entries(answers)) {
      if (t.toLowerCase().startsWith(p.toLowerCase()) && v) return v;
    }
    return '';
  };

  const quiDepose   = exact('Qui dépose');
  // Une seule des 5 questions « Type de facture (…) » est posée selon le
  // service (logique du formulaire) : on prend celle qui a une réponse.
  const type        = byPrefix('Type de facture');
  const entreprise  = exact('Entreprise');
  const dateFacture = exact('Date de la facture');
  const montant     = byPrefix('Montant');
  const fileUrl     = exact('Facture') || byPrefix('Facture');

  const hello = GREETING ? `Hello ${GREETING},` : 'Bonjour,';
  const body = [
    hello,
    '',
    `${quiDepose} vient de déposer une nouvelle facture "${type}" datant du ${dateFacture} d'un montant de ${montant} € chez ${entreprise}. Merci !`,
  ].join('\n');

  let fileName = 'facture.pdf';
  try {
    fileName = decodeURIComponent(new URL(fileUrl).pathname.split('/').pop()) || fileName;
  } catch (e) { /* URL absente ou invalide : nom par défaut */ }

  out.push({
    json: {
      to: TO,
      cc: CC,
      subject: SUBJECT,
      fromName: FROM_NAME,
      body,
      fileUrl,
      fileName,
      formId: fr.form_id,
      submittedAt: fr.submitted_at,
    },
  });
}

return out;
